theorem Summable.exists_max_norm {ι M : Type*} [NormedAddCommGroup M] {g : ι → M}
    (hg : Summable g) {i₁ : ι} (hi₁ : g i₁ ≠ 0) :
    ∃ i₀, g i₀ ≠ 0 ∧ ∀ i, ‖g i‖ ≤ ‖g i₀‖

theorem exists_max_norm_laurent {K : Type*} [NormedField K] {c : ℤ → K} {u : Kˣ}
    (hsum : Summable fun n : ℤ => c n * (u : K) ^ n) {m : ℤ} (hm : c m ≠ 0) :
    ∃ n₀ : ℤ, c n₀ ≠ 0 ∧ ∀ n : ℤ, ‖c n * (u : K) ^ n‖ ≤ ‖c n₀ * (u : K) ^ n₀‖

theorem thetaProd_zero_orbit [CompleteSpace K] {u v : Kˣ}
    (hu : t.thetaProd u = 0) (hv : t.thetaProd v = 0) :
    ∃ k : ℤ, (u : K) = (t.q : K) ^ k * (v : K)

theorem theta_eq_thetaProd_of_laurentCoeffUnique (huniq : LaurentCoeffUnique K) {u₀ : Kˣ}
    (hu₀ : t.theta u₀ ≠ 0) (hnorm : t.theta u₀ = t.thetaProd u₀) (u : Kˣ) :
    t.theta u = t.thetaProd u

lemma point_some_congr {W : WeierstrassCurve.Affine K} {x₁ y₁ x₂ y₂ : K}
    {h₁ : W.Nonsingular x₁ y₁} {h₂ : W.Nonsingular x₂ y₂} (hx : x₁ = x₂) (hy : y₁ = y₂) :
    (WeierstrassCurve.Affine.Point.some x₁ y₁ h₁) = .some x₂ y₂ h₂

theorem defectAnnulusCoeff_eq_zero (h12 : (12 : K) ≠ 0) {u : Kˣ}
    (h1 : 1 < ‖(u : K)‖) (h2 : ‖(t.q : K)‖ * ‖(u : K)‖ < 1) (ℓ : ℤ) :
    t.defectAnnulusCoeff ℓ = 0

lemma const_eq_thetaProdLaurentCoeff_zero {b₀ : K}
    (hb₀ : ∀ u : Kˣ, t.thetaProd u = b₀ * t.theta u) :
    b₀ = t.thetaProdLaurentCoeff 0

theorem w1_eq_smul_thetaBlock {A : Kˣ} {c : ℤ → K}
    (hc : t.IsWeightFamily 1 A c) :
    c = c 0 • t.thetaBlock ((t.q * A)⁻¹)

lemma IsWeightFamily.sub {t : TateParameter K} {k : ℕ} {A : Kˣ} {c d : ℤ → K}
    (hc : t.IsWeightFamily k A c) (hd : t.IsWeightFamily k A d) :
    t.IsWeightFamily k A (c - d)

theorem norm_y_sq_eq_norm_x_cube (h12 : (12 : K) ≠ 0) {x y : K}
    (hxy : y ^ 2 + x * y = x ^ 3 + t.a₄ * x + t.a₆) (hx : 1 < ‖x‖) :
    ‖y‖ ^ 2 = ‖x‖ ^ 3

theorem mem_range_tatePoint_of_annulus {x y : K}
    (hns : t.tateCurve.toAffine.Nonsingular x y) (hx : ‖x‖ < 1) (hy : ‖y‖ < 1) :
    ∃ u : Kˣ, t.tatePoint hmem h12 u = WeierstrassCurve.Affine.Point.some x y hns
